import { useAppStore } from './store/useAppStore';
import { useSocket } from './hooks/useSocket';
import ChatWindow from './components/chat/ChatWindow';
import ChatInput from './components/chat/ChatInput';
import { Badge } from './components/ui/badge';
import { cn } from './lib/utils';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import StateExplorer from './pages/StateExplorer';
import { Tabs, TabsList, TabsTrigger, TabsContent } from './components/ui/tabs';

function App() {
  const {
    connectionStatus,
  } = useAppStore();

  // Initialize WebSocket connection
  useSocket();

  const getConnectionBadgeVariant = () => {
    switch (connectionStatus) {
      case 'connected':
        return 'default';
      case 'connecting':
        return 'secondary';
      case 'disconnected':
        return 'destructive';
      case 'error':
        return 'destructive';
      default:
        return 'outline';
    }
  };

  const getConnectionBadgeText = () => {
    switch (connectionStatus) {
      case 'connected':
        return 'Connected';
      case 'connecting':
        return 'Connecting...';
      case 'disconnected':
        return 'Disconnected';
      case 'error':
        return 'Connection Error';
      default:
        return 'Unknown';
    }
  };
  const clientId = localStorage.getItem('clientId')

  return (
    <Router>
      <div className="flex flex-col h-screen bg-background text-foreground">
        <div className="flex items-center justify-between p-4 border-b border-border">
          <h2 className="text-xl font-semibold">Chatbot</h2>
          <Badge
            variant={getConnectionBadgeVariant()}
            className={cn(connectionStatus === 'connecting' && 'animate-pulse')}
          >
            {getConnectionBadgeText()}
          </Badge>
        </div>

        <Tabs defaultValue="chat" className="w-full h-full flex flex-col">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="chat" asChild>
              <Link to="/">Chat</Link>
            </TabsTrigger>
            <TabsTrigger value="state-explorer" asChild>
              <Link to={`/state-explorer/${clientId || 'YOUR_CLIENT_ID'}`}>State Explorer</Link>
            </TabsTrigger>
          </TabsList>
          <TabsContent value="chat" className="flex flex-col flex-grow h-full">
            <Routes>
              <Route path="/" element={
                <div className="flex flex-col h-full justify-between"> {/* Added justify-between here */}
                  <ChatWindow />
                  <ChatInput />
                </div>
              } />
            </Routes>
          </TabsContent>
          <TabsContent value="state-explorer" className="flex flex-col flex-grow">
            <Routes>
              <Route path="/state-explorer/:clientId" element={<StateExplorer />} />
            </Routes>
          </TabsContent>
        </Tabs>
      </div>
    </Router>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { getState } from '../lib/api';
import { Card, CardContent, CardHeader, CardTitle } from '../components/ui/card';
import { ScrollArea } from '../components/ui/scroll-area';

const StateExplorer: React.FC = () => {
  const [stateData, setStateData] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [clientId, setClientId] = useState<string | null>(null);

  useEffect(() => {
    const storedClientId = localStorage.getItem('clientId');
    if (storedClientId) {
      setClientId(storedClientId);
      getState(storedClientId)
        .then(data => {
          setStateData(data.state); // Access the 'state' object directly
        })
        .catch(err => {
          setError(err.message);
        });
    } else {
      setError('No client ID found in local storage.');
    }
  }, []);

  return (
    <ScrollArea className="h-full p-4">
      <h1 className="text-2xl font-bold mb-4">State Explorer for Client ID: {clientId || 'N/A'}</h1>
      {error && <p className="text-red-500">Error: {error}</p>}
      {stateData ? (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {Object.entries(stateData).map(([key, value]) => (
            <Card key={key}>
              <CardHeader>
                <CardTitle className="capitalize">{key.replace(/_/g, ' ')}</CardTitle>
              </CardHeader>
              <CardContent>
                {value !== null && typeof value !== 'undefined' ? (
                  typeof value === 'string' ? (
                    <pre className="whitespace-pre-wrap text-sm bg-muted p-2 rounded-md overflow-auto max-h-48">
                      {value}
                    </pre>
                  ) : (
                    <pre className="whitespace-pre-wrap text-sm bg-muted p-2 rounded-md overflow-auto max-h-48">
                      {JSON.stringify(value, null, 2)}
                    </pre>
                  )
                ) : (
                  <pre className="whitespace-pre-wrap text-sm bg-muted p-2 rounded-md overflow-auto max-h-48">
                    N/A
                  </pre>
                )}
              </CardContent>
            </Card>
          ))}
        </div>
      ) : (
        !error && <p>Loading state data...</p>
      )}
    </ScrollArea>
  );
};

export default StateExplorer;

